function normalizeProject(p){if(!p||!Array.isArray(p.edges))return p;p.edges=p.edges.map(e=>(e.type==='state'||(p.example&&e.type==='control'&&e.from==='architecture'&&e.to==='normalizer'))?{...e,type:'dependency'}:e);return p;}
try{const saved=window.AccountSync?window.AccountSync.boot.data:JSON.parse(localStorage.getItem('adc-projects-v2')||'null');if(saved){if(C.validateStore(saved)){saved.projects=saved.projects.map(normalizeProject);storeData={...defaults,...saved,prefs:{...defaults.prefs,...saved.prefs}};}else storageError=true;}}catch{storageError=true;}
