async function openDelivery(){try{const p=project();if(!p){location.href='/m/ai-dev-collaboration-workbench/delivery';return;}if(window.AccountSync){const saved=await window.AccountSync.flush();if(!saved)throw Error('请先成功保存画布项目');}const response=await fetch('/api/m/ai-dev-collaboration-workbench/delivery');const data=await response.json();if(!response.ok)throw Error(data.error);let target=data.projects.find(x=>x.source?.kind==='canvas'&&x.source.project_id===p.id&&x.source.version===p.version);if(!target){const r=await fetch('/api/m/ai-dev-collaboration-workbench/delivery',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({operation_id:uid(),action:'create',canvas_project_id:p.id})});const j=await r.json();if(!r.ok)throw Error(j.error);target=j.project;}location.href='/m/ai-dev-collaboration-workbench/delivery?project='+encodeURIComponent(target.id);}catch(e){toast('打开交付失败：'+e.message,'Could not open delivery: '+e.message);}}

function project(){const p=storeData.projects.find(p=>p.id===storeData.active);return normalizeProject(p);}
function persist(touch=false){if(touch&&project())project().updated=new Date().toISOString();storeData.view=view;if(window.AccountSync){window.AccountSync.queue(storeData);return;}try{localStorage.setItem('adc-projects-v2',JSON.stringify(storeData));storageError=false;}catch{storageError=true;}if($('#save-label'))$('#save-label').textContent=storageError?L('保存失败，请导出备份','Save failed; export a backup'):L('已保存在此浏览器','Saved in this browser');}
function toast(cn,en){$('#live').textContent=L(cn,en);$('#live').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#live').classList.remove('show'),2800);}
function node(id,type,title,summary,x,y,stage,artifact,more={}){return {id,type,title,summary,x,y,w:type==='architecture'?290:250,h:type==='architecture'?180:150,stage,artifact,status:'draft',why:B('明确该产物解决的问题。','Clarify the problem this artifact solves.'),intent:B('使意图、职责和验收标准可以追溯。','Keep intent, responsibility and acceptance traceable.'),constraints:'',risks:'',eval:'',evidence:'',...more};}
function exampleProject(){const p={id:uid(),name:B('新闻事件去重','News event deduplication'),goal:B('将重复报道合并为事件，同时保留传播广度。','Group repeated reports into events while preserving source breadth.'),stage:'learn',status:'accepted',version:1,updated:new Date().toISOString(),example:true,camera:{x:50,y:65,z:.85},nodes:[],edges:[]};
 p.nodes=[
 node('problem','problem',B('真实问题','Problem'),B('报道数量不等于事件数量','Reports are not events'),40,60,'explore',B('目标：识别独立事件，避免将重复报道计为多个趋势信号。\n非目标：判断新闻真实性、自动生成投资建议。','Goal: identify distinct events without counting repeated coverage as independent trend signals.\nNon-goals: fact checking or investment advice.'),{why:B('同一发布被多次报道，会夸大趋势。','Repeated coverage can inflate a trend.'),intent:B('把事件强度与传播广度分开。','Separate event frequency from propagation breadth.'),status:'accepted'}),
 node('architecture','architecture',B('系统架构','Architecture'),B('输入 → 归一化 → 事件聚合 → 输出','Input → normalize → group → output'),420,40,'specify',B('Collector 提供报道 → Normalizer 校验 eventId / source → Grouper 按 eventId 聚合 → Presenter 输出事件与来源数。\n状态：已处理事件保留唯一标识与来源集合。','Collector supplies reports → Normalizer validates eventId / source → Grouper groups by eventId → Presenter emits events and source counts.\nState: each event retains its identity and distinct sources.'),{constraints:B('本示例使用显式事件 ID，不调用模型。','This example uses explicit event IDs and no model API.'),status:'accepted'}),
 node('collector','module',B('报道输入','Report input'),B('4 条可检查的样例记录','Four inspectable fixture reports'),40,360,'execute',JSON.stringify(C.fixture,null,2),{why:B('输入可复现，后续验证才可追溯。','Reproducible input makes verification traceable.'),intent:B('保留原始来源，不凭空生成证据。','Preserve original source identifiers.'),status:'verified',evidence:B('内置 fixture：4 条记录，2 个事件。','Bundled fixture: four reports, two events.')}),
 node('normalizer','module',B('输入校验','Input validation'),B('eventId 与 source 必须非空','Require eventId and source'),420,360,'execute',`if (!record.eventId || !record.source) {\n  throw new Error('eventId and source are required');\n}`,{eval:B('缺少 eventId 的记录必须报错。','A record without eventId must fail.'),status:'verified',evidence:B('确定性输入校验；空字段会抛出错误。','Deterministic validation rejects empty fields.')}),
 node('grouper','module',B('事件聚合','Event grouping'),B('按事件归并，独立统计来源','Group by event; count unique sources'),840,340,'execute',B('分组键：eventId\n事件频次：每组计 1 次\n传播广度：distinct(source)\n保留 reportCount 以追溯原始报道量。','Group key: eventId\nEvent frequency: one per group\nSource breadth: distinct(source)\nRetain reportCount for provenance.'),{why:B('去重不能抹掉传播广度。','Deduplication must not erase propagation breadth.'),intent:B('消除重复膨胀，同时保留来源数。','Remove inflation while retaining source counts.'),status:'verified',evidence:B('运行样例：3 条同事件报道 → 1 个事件、2 个来源。','Fixture run: three same-event reports → one event, two sources.')}),
 node('adr','decision',B('按事件计数','Count events'),B('ADR-001 · 保留来源数','ADR-001 · preserve source counts'),840,60,'decide',B('决策：使用显式 eventId 分组，同时单独统计 sourceCount。\n备选：按文章计数；文本相似度去重。\n理由：本闭环先验证事件口径，不引入语义匹配成本。\n代价：需要上游提供可靠事件 ID。\n重审条件：真实来源无法提供一致 ID。','Decision: group by explicit eventId and separately compute sourceCount.\nAlternatives: article counts; text-similarity grouping.\nRationale: verify event-level semantics before semantic matching.\nTrade-off: reliable upstream event IDs required.\nRevisit when real sources lack consistent IDs.'),{status:'accepted'}),
 node('plan','plan',B('最小闭环','Smallest loop'),B('先验证去重，再接入真实来源','Verify grouping before live sources'),40,680,'plan',B('1. 固定 4 条输入\n2. 实现事件分组与来源去重\n3. 比较事件数、来源数、报道数\n4. 满足停止条件后，再讨论真实数据接入','1. Fix four input records\n2. Group events and unique sources\n3. Compare event, source and report counts\n4. Discuss live data only after meeting the stop condition'),{status:'accepted'}),
 node('output','artifact',B('聚合结果','Grouped output'),B('2 个事件 · 来源广度保留','Two events · source breadth retained'),1240,340,'verify',JSON.stringify(C.deduplicate(C.fixture),null,2),{status:'verified',evidence:B('由内置去重函数实际计算；可在验证页复验。','Computed by the bundled function; rerunnable in Verify.')}),
 node('verification','verification',B('验收证据','Verification evidence'),B('3 项期望与实际一致','Three expected values match actuals'),840,680,'verify',B('预期：2 个独立事件；首个事件 2 个来源、3 条报道。\n实际：请查看下方运行结果。\n停止条件：三项断言均成立；不宣称已验证真实数据。','Expected: two distinct events; first event has two sources and three reports.\nActual: see executable evidence below.\nStop condition: all three assertions pass; no claim about live data.'),{status:'verified',eval:B('错误实现按文章计数时，事件数断言应失败。','Counting articles as events must fail the event-count assertion.')}),
 node('risk','risk',B('事件身份风险','Event identity risk'),B('示例不覆盖跨来源语义匹配','Cross-source semantic matching excluded'),1240,680,'learn',B('已接受差异：这个样例只验证确定性聚合，尚未实现自动事件识别。\n下一轮先构造跨来源同事件反例，再判断是否需要模型。','Accepted difference: this fixture verifies deterministic grouping only, not automatic event identity.\nNext: construct cross-source counterexamples before considering a model.'),{status:'accepted',risks:B('错误的 eventId 会产生错误合并或漏合并。','Incorrect event IDs can cause false or missed merges.')})
 ];
 p.edges=[['problem','architecture','dependency'],['architecture','normalizer','control'],['collector','normalizer','data'],['normalizer','grouper','data'],['adr','grouper','dependency'],['grouper','output','data'],['grouper','verification','state'],['plan','collector','control'],['output','verification','dependency'],['verification','risk','state']].map(([from,to,type],i)=>({id:'edge-'+i,from,to,type}));return p;}
function createProject(name,goal,stage){const p={id:uid(),name,goal,stage,status:'draft',version:1,updated:new Date().toISOString(),example:false,camera:{x:55,y:80,z:1},nodes:[node('problem','problem',B('问题定义','Problem brief'),goal,40,100,'explore',goal),node('architecture','architecture',B('架构草案','Architecture draft'),B('明确职责、接口与流类型','Define responsibilities, interfaces and flows'),430,100,'specify',''),node('verification','verification',B('验证计划','Verification plan'),B('先定义什么算做好','Define what counts as correct'),860,100,'verify','')],edges:[{id:uid(),from:'problem',to:'architecture',type:'dependency'},{id:uid(),from:'architecture',to:'verification',type:'dependency'}]};storeData.projects.push(p);storeData.active=p.id;view='canvas';selected=null;persist(true);render();fitCanvas();return p;}
function openExample(){let p=storeData.projects.find(p=>p.example);if(!p){p=normalizeProject(exampleProject());storeData.projects.push(p);}else normalizeProject(p);storeData.active=p.id;view='canvas';selected=null;full=false;persist();render();fitCanvas();}
function switchView(next){if(next==='delivery'){openDelivery();return;}if(next!=='home'&&next!=='projects'&&next!=='method'&&next!=='releases'&&next!=='settings'&&!project()){view='projects';}else view=next;full=false;selected=null;query='';persist();render();}
function applyPrefs(){if(!document.getElementById('entry-css')){const link=document.createElement('link');link.id='entry-css';link.rel='stylesheet';link.href='/apps/ai-dev-collaboration-workbench/entry.css';document.head.append(link);}document.documentElement.lang=language==='zh'?'zh-CN':'en';document.documentElement.dataset.theme=storeData.prefs.theme;document.documentElement.dataset.reduce=storeData.prefs.reduce?'true':'false';document.title=L('AI 开发协作 · 项目工作台','AI Development Collaboration · Workspace');}
function languageButton(){return `<button class="language" data-action="language" title="${L('Switch to English','切换为中文')}">${language==='zh'?'EN':'中文'}</button>`;}
function decorateLegend(){const legend=$('.canvas-legend');if(legend&&!legend.querySelector('.legend-status'))legend.insertAdjacentHTML('beforeend',`<span class="legend-status">${L('节点状态由标签表示','Node state is shown by status labels')}</span>`);}
function render(){applyPrefs();graphObserver?.disconnect();$('#app').innerHTML=view==='home'?home():shell();if(view==='canvas'){mountCanvas();decorateLegend();}if(view==='home')drawDemo();bindLocal();}
function home(){return `<header class="home-header"><a href="#" data-action="home" class="wordmark" aria-label="AI Development Collaboration">${icon('canvas')}<span>AI Development Collaboration</span></a><div class="home-actions"><a href="/m/ai-dev-collaboration-workbench/delivery" class="text-button">${L('交付工作台','Delivery workspace')}</a>${languageButton()}</div></header><main class="home-main"><section class="hero"><p class="eyebrow">${L('人机协作开发 · 方法与工作空间','Human–AI development · method & workspace')}</p><h1>${L('让模糊想法，成为<br>结构清晰、可验证的系统。','Turn ambiguous ideas into<br>structured, verifiable systems.')}</h1><p class="hero-note">${L('从当前阶段开始。把问题、架构、决策与证据放进同一张项目画布。','Start where you are. Connect problems, architecture, decisions and evidence on one project canvas.')}</p>${btn('new-project',L('开始项目','Start a Project'),'plus','primary hero-start')}<div class="hero-links">${btn('view-method',L('探索方法','Explore Methodology'),'route','text-button')}${btn('example',L('查看示例项目','View Example Project'),'chevron','text-button')}</div><span class="hero-foot">${L('画布梳理思路 · 交付工作台连接执行与证据','Map your intent · connect execution with evidence')}</span></section><section class="entry-section"><div class="section-heading"><div><p class="eyebrow">${L('从当前状态进入','Enter from your current state')}</p><h2>${L('你现在处于哪一步？','Where are you now?')}</h2><p>${L('选择最接近的状态，项目会从对应阶段开始；不必机械地从 Explore 开始。','Choose the closest state. Your project starts there; you do not have to begin at Explore.')}</p></div></div><div class="entry-grid">${entryStates.map((e,i)=>`<button class="entry-choice" data-action="entry" data-stage="${e.stage}"><small>0${i+1}</small><strong>${L(entryZh[i][0],e.label)}</strong><span>${L(entryZh[i][1],e.note)}</span><em>${e.route.join(' → ')}</em></button>`).join('')}</div></section><section class="how-section"><div class="section-heading"><div><p class="eyebrow">${L('工作如何成形','How work takes shape')}</p><h2>${L('每一步，都留下可检查的产物。','Every step leaves something inspectable.')}</h2></div>${btn('demo-toggle',demoPaused?L('播放演示','Play demo'):L('暂停演示','Pause demo'),'','text-button')}</div><div class="demo-layout"><div id="demo-stages"></div><div class="demo-board" id="demo-board" aria-label="${L('阶段与产物演示','Stage and artifact demonstration')}"></div></div><p class="quiet">${L('演示展示一条可能路径。实际项目可从任意阶段进入，也可因新证据回退。','This is one possible path. Real projects can enter at any stage or return when new evidence appears.')}</p></section><section class="example-preview"><div><p class="eyebrow">${L('完整示例 · 确定性验证','Worked example · deterministic verification')}</p><h2>${L('4 条报道，2 个事件。','Four reports. Two events.')}</h2><p>${L('保留传播广度，避免重复计数。查看架构、关键取舍与实际运行的验证结果。','Preserve source breadth without double counting. Inspect architecture, trade-offs and executable evidence.')}</p>${btn('example',L('检查示例产物','Inspect example artifacts'),'chevron','text-button')}</div><div class="example-strip"><span>4 ${L('报道','reports')}</span><b>→</b><span>${L('事件聚合','Grouping')}</span><b>→</b><span>2 ${L('事件','events')}<small>3/3 ${L('断言通过','assertions pass')}</small></span></div></section><section class="home-method"><p class="eyebrow">${L('九类问题，不是强制瀑布流程','Nine questions, not a mandatory waterfall')}</p><div>${stages.map((s,i)=>btn('stage',L(stageCN[i],s.name),'','method-link',`data-stage="${s.id}"`)).join('')}</div></section>${storeData.projects.length?`<section class="recent"><h2>${L('继续已有项目','Continue a project')}</h2>${projectRows()}</section>`:''}</main><footer class="home-footer"><span>${window.AccountSync?L('项目按账号保存 · 管理员可为排障与改进只读查看，访问留有记录。','Saved to your account · Administrator reads for troubleshooting and improvements are logged.'):L('本地预览：仅保存在此浏览器。','Local preview: saved in this browser only.')}</span><span>Skill 0.1.0 / Site 1.2</span></footer>`;}
function projectRows(){return storeData.projects.map(p=>`<button class="project-row" data-action="open-project" data-id="${p.id}"><span>${icon('folder')}<strong>${esc(value(p.name))}</strong>${p.example?`<small>${L('样例','Example')}</small>`:''}</span><span>${stageLabel(p.stage)} ${icon('chevron')}</span></button>`).join('');}
function shell(){const p=project();return `<div class="work-shell"><nav class="rail" aria-label="${L('主导航','Main navigation')}">${ib('home',L('首页','Home'),'home')}<div class="rail-links">${navs.map(([id,ic,cn,en])=>`<button data-action="view-${id}" class="rail-item ${view===id?'active':''}" title="${L(cn,en)}" aria-current="${view===id?'page':'false'}">${icon(ic)}<span>${L(cn,en)}</span></button>`).join('')}</div>${languageButton()}</nav>${storeData.prefs.sidebar?`<aside class="browser"><header><span>${L('项目浏览器','Project browser')}</span>${ib('sidebar',L('收起浏览器','Collapse browser'),'panel')}</header><button class="project-name" data-action="view-projects">${icon('folder')}${esc(p?value(p.name):L('选择项目','Choose project'))}</button>${p?`<p class="tiny">${L('项目产物','PROJECT ARTIFACTS')}</p><nav class="file-nav">${p.nodes.map(n=>`<button data-action="open-node" data-id="${n.id}" class="${selected===n.id?'active':''}">${icon(n.type==='decision'?'branch':'file')}<span>${esc(value(n.title))}</span><i class="state-dot ${n.status}"></i></button>`).join('')}</nav>${btn('add-node',L('添加产物','Add artifact'),'plus','text-button')}`:`<p class="quiet">${L('开始一个项目，或打开完整示例。','Start a project or open the worked example.')}</p>`}<div class="browser-bottom"><span id="save-label">${storageError?L('保存不可用，请导出备份','Saving unavailable; export a backup'):L('已保存在此浏览器','Saved in this browser')}</span><small>${L('推理继续在你的 Agent 中进行','Reasoning stays in your Agent')}</small></div></aside>`:''}<main class="work-main"><header class="toolbar"><div class="toolbar-left">${!storeData.prefs.sidebar?ib('sidebar',L('展开浏览器','Expand browser'),'panel'):''}${view==='canvas'?canvasTools():`<strong>${L(navs.find(n=>n[0]===view)?.[2]||'项目',navs.find(n=>n[0]===view)?.[3]||'Project')}</strong>`}</div><div class="toolbar-right">${p?`<label class="stage-picker"><span class="sr-only">${L('当前阶段','Current stage')}</span><select id="project-stage">${stages.map(s=>`<option value="${s.id}" ${p.stage===s.id?'selected':''}>${stageLabel(s.id)}</option>`).join('')}</select></label><span class="project-status">${value(statusLabels[p.status])}</span><span class="meta">v${p.version} · ${new Date(p.updated).toLocaleDateString(language==='zh'?'zh-CN':'en-US',{month:'short',day:'numeric'})}</span>${ib('export',L('导出项目','Export project'),'download')}`:''}</div></header>${view==='canvas'?`<div class="canvas-layout ${full?'full-detail-mode':''}"><div id="viewport" class="viewport" data-theme="${storeData.prefs.canvasTheme}"><div class="canvas-instructions">${L('拖动空白处平移 · 拖动节点调整布局','Drag background to pan · drag nodes to arrange')}</div><div id="world"><svg id="edges" width="2400" height="2000" aria-label="${L('项目关系连线','Project relationships')}"></svg><div id="nodes"></div></div><div class="canvas-legend">${Object.entries(flowLabels).filter(([k])=>k!=='all').map(([k,v])=>`<span><i class="legend-line ${k}"></i>${value(v)}</span>`).join('')}</div><div id="semantic-label" class="semantic-label"></div></div>${selected?inspector():''}</div>`:`<div class="page-body">${pageContent()}</div>`}</main></div>`;}
function canvasTools(){return `${ib('zoom-out',L('缩小','Zoom out'),'minus')}<button data-action="zoom-reset" id="zoom-label" class="zoom-label">100%</button>${ib('zoom-in',L('放大','Zoom in'),'plus')}${ib('fit',L('适应画布','Fit canvas'),'fit')}<span class="separator"></span><label class="flow-filter-label" title="${L('执行流：实际执行顺序、触发和编排；数据流：数据或产物传递、转换；依赖/依据：前置条件、决策依据或验收依据。节点状态由状态标签表示。','Execution: actual order, triggers and orchestration; Data: data or artifacts passed or transformed; Dependency / basis: prerequisites, decision basis or verification basis. Node state is shown by status labels.')}" ><span class="sr-only">${L('关系筛选','Flow filter')}</span><select id="flow-filter">${Object.entries(flowLabels).map(([k,v])=>`<option value="${k}" ${filter===k?'selected':''}>${value(v)}</option>`).join('')}</select></label><span id="flow-help" class="flow-help">${value(flowHelp[filter])}</span><label class="search-field">${icon('search')}<input id="node-search" placeholder="${L('查找产物','Find artifacts')}" aria-label="${L('查找产物','Find artifacts')}" value="${esc(query)}"></label><button class="icon-btn ${focus?'pressed':''}" data-action="focus" aria-pressed="${focus}" aria-label="${L('聚焦关联','Focus relationships')}">${icon('focus')}</button>${ib('add-node',L('添加产物','Add artifact'),'plus')}`;}
function pageContent(){switch(view){case'projects':return `<div class="page-heading"><div><p class="eyebrow">${L('你的工作空间','Your workspace')}</p><h1>${L('项目','Projects')}</h1></div>${btn('new-project',L('开始项目','Start a Project'),'plus','primary')}</div>${storeData.projects.length?projectRows():`<div class="empty"><h2>${L('从一个真实问题开始。','Start with a real problem.')}</h2><p>${L('明确当前阶段，再创建你的第一张项目画布。','Locate your current stage, then create your first project canvas.')}</p>${btn('example',L('先看看完整示例','Inspect the worked example'),'chevron','text-button')}</div>`}`;case'method':return methodPage();case'artifacts':return artifactPage();case'decisions':return artifactPage('decision');case'verification':return verificationPage();case'releases':return releasePage();case'settings':return settingsPage();default:return '';}}
function mountCanvas(){const vp=$('#viewport');if(!vp||!project())return;vp.style.setProperty('--grid-alpha',storeData.prefs.strength/100);vp.dataset.grid=storeData.prefs.grid;drawGraph();vp.onpointerdown=e=>{if(e.target.closest('button'))return;const n=e.target.closest('.graph-node');activeDrag={id:n?.dataset.id,startX:e.clientX,startY:e.clientY,cam:{...project().camera},pos:n?{...project().nodes.find(v=>v.id===n.dataset.id)}:null,moved:false};vp.setPointerCapture(e.pointerId);};vp.onpointermove=e=>{if(!activeDrag)return;const d=activeDrag,dx=e.clientX-d.startX,dy=e.clientY-d.startY;d.moved ||=Math.abs(dx)+Math.abs(dy)>5;if(d.id){const n=project().nodes.find(v=>v.id===d.id);n.x=Math.max(0,d.pos.x+dx/project().camera.z);n.y=Math.max(0,d.pos.y+dy/project().camera.z);}else{project().camera.x=d.cam.x+dx;project().camera.y=d.cam.y+dy;}drawGraph();};vp.onpointerup=()=>{if(!activeDrag)return;const d=activeDrag;if(d.id&&d.moved){const n=project().nodes.find(v=>v.id===d.id);Object.assign(n,C.place(n,n.x,n.y,project().nodes));}swallowClick=d.moved;activeDrag=null;if(d.id&&!d.moved){selectNode(d.id);return;}persist();drawGraph();};vp.onwheel=e=>{e.preventDefault();zoom(e.deltaY<0?1.1:1/1.1,e.clientX,e.clientY);};graphObserver=new ResizeObserver(()=>drawGraph());graphObserver.observe(vp);}
function drawGraph(){const p=project(),world=$('#world');if(!p||!world)return;const {x,y,z}=p.camera;world.style.transform=`translate(${x}px,${y}px) scale(${z})`;const level=storeData.prefs.density==='auto'?(z<.65?'far':z>1.15?'near':'normal'):storeData.prefs.density;const related=selected&&focus?C.neighbors(selected,p.edges):null;$('#nodes').innerHTML=p.nodes.map(n=>{const dim=(related&&!related.has(n.id))||(query&&!`${value(n.title)} ${value(n.summary)}`.toLowerCase().includes(query.toLowerCase()));return `<article tabindex="0" role="button" aria-label="${esc(value(n.title))}" data-action="select-node" data-id="${n.id}" class="graph-node type-${n.type} ${n.id===selected?'selected':''} ${dim?'dim':''} level-${level}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;min-height:${n.h}px;--readable:${Math.max(1,.72/z)}"><div class="node-kicker">${value(typeLabels[n.type])}<span class="status-dot ${n.status}" title="${value(statusLabels[n.status])}"></span></div><h3>${esc(value(n.title))}</h3>${level!=='far'?`<p>${esc(value(n.summary))}</p>`:''}${level==='near'?`<small>${stageLabel(n.stage)} · ${p.edges.filter(e=>e.from===n.id||e.to===n.id).length} ${L('关联','links')}<br>${value(statusLabels[n.status])}</small>`:''}</article>`;}).join('');$('#edges').innerHTML=`<defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="7" refY="3" orient="auto"><path d="M0,0 L7,3 L0,6" fill="none" stroke="currentColor"/></marker></defs>`+p.edges.filter(e=>filter==='all'||e.type===filter).map(e=>{const a=p.nodes.find(n=>n.id===e.from),b=p.nodes.find(n=>n.id===e.to);if(!a||!b)return '';const ax=a.x+a.w,ay=a.y+a.h/2,bx=b.x,by=b.y+b.h/2;const direct=e.from===selected||e.to===selected;return `<path class="edge ${e.type} ${selected&&focus&&!direct?'dim':''} ${direct?'highlight':''}" d="M${ax},${ay} C${ax+100},${ay} ${bx-100},${by} ${bx},${by}" marker-end="url(#arrow)"><title>${esc(value(a.title))} → ${esc(value(b.title))} · ${value(flowLabels[e.type])}</title></path>`;}).join('');$('#zoom-label').textContent=Math.round(z*100)+'%';$('#semantic-label').textContent=L({far:'远景 · 标题与状态',normal:'常规 · 摘要与状态',near:'近景 · 元数据与关联'}[level],{far:'Overview · title & state',normal:'Normal · summary & state',near:'Detail · metadata & links'}[level]);}
function zoom(f,cx,cy){const vp=$('#viewport');if(!vp)return;const c=project().camera,r=vp.getBoundingClientRect(),px=cx===undefined?r.width/2:cx-r.left,py=cy===undefined?r.height/2:cy-r.top,nz=Math.min(1.7,Math.max(.4,c.z*f));c.x=px-(px-c.x)*nz/c.z;c.y=py-(py-c.y)*nz/c.z;c.z=nz;drawGraph();persist();}
function fitCanvas(){const vp=$('#viewport'),p=project();if(!vp||!p)return;const width=Math.max(...p.nodes.map(n=>n.x+n.w))+70,height=Math.max(...p.nodes.map(n=>n.y+n.h))+90;p.camera={x:35,y:45,z:Math.max(.4,Math.min(1,(vp.clientWidth-60)/width,(vp.clientHeight-90)/height))};drawGraph();persist();}
function selectNode(id){selected=id;view='canvas';full=false;render();const n=project().nodes.find(n=>n.id===id),vp=$('#viewport'),c=project().camera;if(n&&vp){const right=(n.x+n.w)*c.z+c.x,bottom=(n.y+n.h)*c.z+c.y;if(right>vp.clientWidth-30)c.x-=right-vp.clientWidth+30;if(n.x*c.z+c.x<20)c.x=20-n.x*c.z;if(bottom>vp.clientHeight-55)c.y-=bottom-vp.clientHeight+55;if(n.y*c.z+c.y<30)c.y=30-n.y*c.z;drawGraph();}persist();}
function evidenceTable(){const names={unique:L('不同事件数量','Unique events'),breadth:L('首个事件的独立来源','Distinct sources for first event'),reports:L('首个事件的报道数','Reports for first event')};return `<table><thead><tr><th>${L('断言','Assertion')}</th><th>${L('预期','Expected')}</th><th>${L('实际','Actual')}</th><th>${L('结果','Result')}</th></tr></thead><tbody>${C.evidence().map(v=>`<tr><td>${names[v.id]}</td><td>${v.expected}</td><td>${v.actual}</td><td class="pass">${v.pass?'✓':'×'} ${v.pass?L('通过','Pass'):L('失败','Fail')}</td></tr>`).join('')}</tbody></table>`;}
function inspector(){const p=project(),n=p.nodes.find(n=>n.id===selected);if(!n)return '';return `<aside class="inspector ${full?'expanded':''}" style="--panel-width:${storeData.prefs.panelWidth}px" aria-label="${L('产物详情','Artifact details')}">${!full?'<div class="resize-handle" role="separator" tabindex="0" aria-label="Resize detail panel" aria-orientation="vertical"></div>':''}<header class="inspector-header"><span>${value(typeLabels[n.type])}</span><div>${ib('full',full?L('返回画布','Back to canvas'):L('全页阅读','Read full page'),full?'canvas':'expand')}${ib('close-detail',L('关闭详情','Close details'),'close')}</div></header><div class="detail-scroll"><div class="detail-main"><h1>${esc(value(n.title))}</h1><section id="artifact-result"><div class="section-heading"><h2>${L('产物','Artifact')}</h2>${btn('edit-node',L('编辑','Edit'),'edit','text-button')}</div><pre class="artifact-content">${esc(value(n.artifact)||L('尚无产物。编辑后记录可检查的结果。','No artifact yet. Edit to capture an inspectable result.'))}</pre></section><section id="artifact-summary"><h2>${L('摘要与状态','Summary & status')}</h2><p>${esc(value(n.summary))}</p><span class="status-tag ${n.status}">${value(statusLabels[n.status])}</span> <small>${stageLabel(n.stage)}</small></section><section id="artifact-evidence"><h2>${L('验证证据','Verification evidence')}</h2>${p.example&&n.type==='verification'?evidenceTable():`<p class="preserve">${esc(value(n.evidence)||L('尚未记录证据。草稿不代表已验证。','No evidence recorded. A draft is not verified.'))}</p>`}</section><section id="artifact-related"><h2>${L('相关产物','Related artifacts')}</h2>${p.edges.filter(e=>e.from===n.id||e.to===n.id).map(e=>{const other=p.nodes.find(v=>v.id===(e.from===n.id?e.to:e.from));return `<button class="related-link" data-action="open-node" data-id="${other.id}"><span>${esc(value(other.title))}</span><small>${value(flowLabels[e.type])} ${e.from===n.id?'→':'←'}</small></button>`;}).join('')||`<p>${L('暂无关联','No relationships yet')}</p>`}</section><details id="artifact-method"><summary>${L('方法依据 · WHY / INTENT / 约束 / 风险 / EVAL','Method rationale · WHY / INTENT / constraints / risks / EVAL')}</summary>${['why','intent','constraints','risks','eval'].map(k=>`<h3>${({why:'WHY',intent:'INTENT',constraints:L('约束','Constraints'),risks:L('风险','Risks'),eval:'EVAL'})[k]}</h3><p class="preserve">${esc(value(n[k])||L('待补充','To be documented'))}</p>`).join('')}${btn('stage',L('查看阶段方法','Read stage methodology'),'route','text-button',`data-stage="${n.stage}"`)}</details></div>${full?`<nav class="detail-index" aria-label="${L('本页目录','On this page')}"><small>${L('本页内容','On this page')}</small><a href="#artifact-result">${L('产物','Artifact')}</a><a href="#artifact-summary">${L('摘要与状态','Summary & status')}</a><a href="#artifact-evidence">${L('验证证据','Evidence')}</a><a href="#artifact-related">${L('相关产物','Related artifacts')}</a><small>v${p.version}<br>${new Date(p.updated).toLocaleString(language==='zh'?'zh-CN':'en-US')}</small></nav>`:''}</div></aside>`;}
function methodPage(){const s=stages.find(s=>s.id===methodStage),d=Object.values(stageDetails[s.id]),labels=['WHY','WHAT','INTENT',L('输入','Inputs'),L('输出','Outputs'),L('关键问题','Key questions'),L('常见错误','Common errors')];return `<div class="page-heading"><div><p class="eyebrow">${L('可复用方法 · 按当前问题进入','Reusable methodology · enter by your current question')}</p><h1>${L('方法地图','Methodology map')}</h1><p>${L('阶段允许跳转、回退与并行。退出条件帮助判断，不强制串行。','Stages allow jumps, returns and parallel work. Exit criteria guide judgment without enforcing a sequence.')}</p></div></div><div class="method-map">${stages.map((x,i)=>`<button data-action="stage" data-stage="${x.id}" class="${x.id===s.id?'active':''}"><small>0${i+1}</small><strong>${stageLabel(x.id)}</strong><span>${t(x.question)}</span></button>`).join('')}</div><article class="method-detail"><div class="section-heading"><h2>${stageLabel(s.id)}</h2>${btn('new-at-stage',L('从此阶段开始项目','Start a project here'),'plus','primary')}</div><h3>${t(s.question)}</h3><dl>${d.map((v,i)=>`<dt>${labels[i]}</dt><dd>${t(v)}</dd>`).join('')}<dt>${L('退出条件','Exit criteria')}</dt><dd>${t(s.exit)}</dd></dl><h3>${L('人工与 AI 分工','Human and AI responsibilities')}</h3><p>${L('人：','Human: ')}${t(s.human)}</p><p>AI: ${t(s.ai)}</p><h3>${L('阶段模板','Stage template')}</h3><pre>${esc(s.fields.map(f=>`${t(f[0])}\n${t(f[1])}`).join('\n\n'))}</pre>${btn('copy-stage',L('复制模板','Copy template'),'file','text-button')}<h3>${L('关联项目产物','Linked project artifacts')}</h3>${project()?.nodes.filter(n=>n.stage===s.id).map(n=>btn('open-node',value(n.title),'file','related-link',`data-id="${n.id}"`)).join('')||`<p>${L('当前阶段尚无项目产物。','No project artifacts for this stage yet.')}</p>`}</article>`;}
function artifactPage(type){const p=project(),nodes=p.nodes.filter(n=>!type||n.type===type);return `<div class="page-heading"><div><p class="eyebrow">${esc(value(p.name))}</p><h1>${type?L('决策记录','Decision records'):L('项目产物','Project artifacts')}</h1></div>${btn('add-node',L('添加产物','Add artifact'),'plus','primary')}</div>${nodes.map(n=>`<button class="artifact-row" data-action="open-node" data-id="${n.id}"><div><small>${value(typeLabels[n.type])} · ${stageLabel(n.stage)}</small><h2>${esc(value(n.title))}</h2><p>${esc(value(n.artifact).slice(0,180)||value(n.summary))}</p></div><span class="status-tag ${n.status}">${value(statusLabels[n.status])}</span></button>`).join('')||`<div class="empty">${L('尚无决策记录。添加决策产物，记录选择、替代方案与重新评估条件。','No decisions yet. Add a decision artifact with choices, alternatives and revisit conditions.')}</div>`}`;}
function verificationPage(){return `<div class="page-heading"><div><h1>${L('验证与证据','Verification & evidence')}</h1><p>${L('验证必须能区分正确实现与错误实现。','Verification must distinguish correct implementations from wrong ones.')}</p></div>${project().example?btn('rerun',L('重新运行样例','Rerun fixture'),'check','primary'):''}</div>${project().example?`<h2>${L('事件去重 · 实际计算','Event deduplication · live calculation')}</h2>${evidenceTable()}<p>${L('范围：4 条固定数据的确定性聚合。不覆盖实时抓取、语义匹配或生产性能。','Scope: deterministic grouping of four fixed records. Does not cover live ingestion, semantic matching or production performance.')}</p><details><summary>${L('查看输入与实际输出','Inspect input and actual output')}</summary><pre>${esc(JSON.stringify({input:C.fixture,output:C.deduplicate(C.fixture)},null,2))}</pre></details>`:''}<h2>${L('验证产物','Verification artifacts')}</h2>${project().nodes.filter(n=>n.type==='verification').map(n=>btn('open-node',value(n.title),'check','related-link',`data-id="${n.id}"`)).join('')}`;}
function releasePage(){return `<div class="page-heading"><div><h1>${L('版本与验收','Releases & acceptance')}</h1><p>${L('方法来源与网站实现分别记录。','Method source and site implementation are tracked separately.')}</p></div></div><div class="release-entry"><small>2026-09-15</small><h2>Site 1.0 · ${L('空间工作台','Spatial workspace')}</h2><p>${L('中文默认、中英切换、可保存项目、关系画布、三级语义缩放、可调整详情面板与完整阅读。','Chinese default with English switching, saved projects, relationship canvas, three semantic zoom levels, resizable inspector and full reading.')}</p><p>${L('验收依据：DESIGN_AI_Development_Collaboration_v1.md。主观三秒识别、模糊层级与风格感受需由你最终确认。','Acceptance source: DESIGN_AI_Development_Collaboration_v1.md. Three-second recognition, blur hierarchy and style judgment require your final review.')}</p><a href="/apps/ai-dev-collaboration-workbench/acceptance.html" target="_blank">${L('查看逐项验收记录','Open acceptance record')}</a></div><div class="release-entry"><small>2026-09-15T17:35:48+08:00</small><h2>Skill 0.1.0</h2><p>GPT-5.6 Sol</p><p>${L('九阶段协作方法、模块卡、ADR 与验证计划来自上传的原始 Skill 包。','Nine-stage methodology, module cards, ADRs and verification plans originate from the uploaded Skill package.')}</p></div>`;}
function settingSelect(key,title,options){return `<label class="setting-row"><span>${title}</span><select data-pref="${key}">${options.map(([v,cn,en])=>`<option value="${v}" ${storeData.prefs[key]===v?'selected':''}>${L(cn,en)}</option>`).join('')}</select></label>`;}
function settingsPage(){return `<div class="page-heading"><div><h1>${L('设置','Settings')}</h1><p>${window.AccountSync?L('偏好与项目一起保存到你的账号。','Preferences are saved to your account with your projects.'):L('偏好保存在当前浏览器。','Preferences are saved in this browser.')}</p></div></div><div class="settings-list">${settingSelect('theme',L('界面主题','Interface theme'),[['light','浅色','Light'],['dark','深色','Dark']])}${settingSelect('canvasTheme',L('画布主题','Canvas theme'),[['light','浅色','Light'],['dark','深色','Dark']])}${settingSelect('grid',L('网格','Grid'),[['off','关闭','Off'],['dots','点阵','Dots'],['lines','线框','Lines']])}<label class="setting-row"><span>${L('网格强度','Grid strength')}</span><input type="range" min="3" max="35" value="${storeData.prefs.strength}" data-pref="strength" aria-label="${L('网格强度','Grid strength')}"></label>${settingSelect('density',L('节点信息密度','Node information density'),[['auto','随缩放变化','Follow zoom'],['far','精简','Compact'],['normal','常规','Normal'],['near','详细','Detailed']])}${['reduce','sidebar'].map(k=>`<label class="setting-row"><span>${k==='reduce'?L('减少动态效果','Reduce motion'):L('显示产物浏览器','Show artifact browser')}</span><input type="checkbox" data-pref="${k}" ${storeData.prefs[k]?'checked':''}></label>`).join('')}<div class="setting-row"><span>${L('语言','Language')}</span>${languageButton()}</div></div><h2>WebMCP Site Tools</h2><p>${webmcpState==='ready'?L('工具已向当前浏览器注册。','Tools are registered with this browser.'):L('当前浏览器未提供 WebMCP。网站的手动操作仍可使用。','This browser does not expose WebMCP. Manual site operations remain available.')}</p><p class="quiet">read_methodology · get_module_template · save_module_card · read_release · get_verification_plan</p><h2>${L('数据与备份','Data & backups')}</h2><p>${window.AccountSync?L('项目按账号同步，可以跨设备继续使用。建议定期导出 JSON 备份；有未保存修改时请先在“我的账号”查看状态。','Projects sync across devices through your account. Export JSON backups regularly; check Account if changes are waiting to save.'):L('本地预览仅保存在当前浏览器。导出 JSON 可备份，并可在这里恢复。','This local preview saves only in this browser. Export JSON to back up and restore it here.')}</p>${btn('import',L('导入项目 JSON','Import project JSON'),'folder','text-button')}${storageError?`<p role="alert">${L('本地存储不可用或现有数据无法读取。请导出备份。','Local storage is unavailable or existing data could not be read. Please export a backup.')}</p>`:''}`;}
function field(name,label,val='',area=false,required=false){return `<label class="form-field"><span>${label}</span>${area?`<textarea name="${name}" ${required?'required':''} rows="${name==='artifact'?9:3}" maxlength="10000">${esc(value(val))}</textarea>`:`<input name="${name}" value="${esc(value(val))}" ${required?'required':''} maxlength="200">`}</label>`;}
function showDialog(title,body,onSubmit){const d=$('#editor');d.innerHTML=`<form><header><h2>${title}</h2>${ib('cancel-dialog',L('取消','Cancel'),'close','type="button"')}</header>${body}<p id="form-error" role="alert"></p><footer><button type="button" data-action="cancel-dialog">${L('取消','Cancel')}</button><button type="submit" class="primary">${L('保存','Save')}</button></footer></form>`;d.querySelector('form').onsubmit=e=>{e.preventDefault();try{onSubmit(Object.fromEntries(new FormData(e.target)));d.close();}catch(err){$('#form-error').textContent=L('无法保存：','Could not save: ')+err.message;}};d.showModal();}
function newProjectDialog(stage='explore'){showDialog(L('开始项目','Start a project'),field('name',L('项目名称','Project name'),'',false,true)+field('goal',L('希望解决什么问题？','What problem should this solve?'),'',true,true)+`<label class="form-field"><span>${L('从当前阶段进入','Enter at your current stage')}</span><select name="stage">${stages.map(s=>`<option value="${s.id}" ${stage===s.id?'selected':''}>${stageLabel(s.id)} — ${t(s.state)}</option>`).join('')}</select></label><p class="quiet">${L('先创建问题、架构草案和验证计划；之后随项目演进补齐。','Begin with a problem brief, architecture draft and verification plan; develop them as you learn.')}</p>`,f=>createProject(f.name.trim(),f.goal.trim(),f.stage));}
function editNodeDialog(isNew=false){const p=project();if(!p){newProjectDialog();return;}const n=isNew?node(uid(),'module','','',80,80,p.stage,''):p.nodes.find(n=>n.id===selected);showDialog(isNew?L('添加产物','Add artifact'):L('编辑产物','Edit artifact'),field('title',L('名称','Name'),n.title,false,true)+`<div class="form-pair"><label class="form-field"><span>${L('类型','Type')}</span><select name="type">${Object.entries(typeLabels).map(([k,v])=>`<option value="${k}" ${n.type===k?'selected':''}>${value(v)}</option>`).join('')}</select></label><label class="form-field"><span>${L('阶段','Stage')}</span><select name="stage">${stages.map(s=>`<option value="${s.id}" ${n.stage===s.id?'selected':''}>${stageLabel(s.id)}</option>`).join('')}</select></label></div>`+field('artifact',L('产物内容 · 结果优先','Artifact content · result first'),n.artifact,true,true)+field('summary',L('WHAT · 职责或摘要','WHAT · responsibility or summary'),n.summary,true,true)+field('evidence',L('验证证据','Verification evidence'),n.evidence,true)+`<label class="form-field"><span>${L('状态（已验证必须提供证据）','Status (verified requires evidence)')}</span><select name="status">${Object.entries(statusLabels).map(([k,v])=>`<option value="${k}" ${n.status===k?'selected':''}>${value(v)}</option>`).join('')}</select></label><details><summary>${L('方法依据','Method rationale')}</summary>${field('why','WHY',n.why,true)}${field('intent','INTENT',n.intent,true)}${field('constraints',L('约束','Constraints'),n.constraints,true)}${field('risks',L('风险','Risks'),n.risks,true)}${field('eval','EVAL',n.eval,true)}</details><div class="form-pair"><label class="form-field"><span>${L('添加一条指向此产物的关联','Add an incoming relationship')}</span><select name="related"><option value="">${L('不添加','None')}</option>${p.nodes.filter(v=>v.id!==n.id).map(v=>`<option value="${v.id}">${esc(value(v.title))}</option>`).join('')}</select></label><label class="form-field"><span>${L('关系类型','Flow type')}</span><select name="flow">${Object.entries(flowLabels).filter(([k])=>k!=='all').map(([k,v])=>`<option value="${k}">${value(v)}</option>`).join('')}</select></label></div>`,f=>{if(f.status==='verified'&&!f.evidence.trim())throw Error(L('请记录可检查的证据。','Add inspectable evidence.'));if(f.type==='module')C.validateCard({name:f.title,what:f.summary,why:f.why,intent:f.intent});const changes=Object.fromEntries(['title','type','stage','artifact','summary','evidence','status','why','intent','constraints','risks','eval'].map(k=>[k,f[k]]));Object.assign(n,changes);if(isNew)p.nodes.push(C.place(n,n.x,n.y,p.nodes));if(f.related)p.edges.push({id:uid(),from:f.related,to:n.id,type:f.flow});p.version++;persist(true);selectNode(n.id);});}
async function saveModuleCard(raw){const f=C.validateCard(raw),p=project();if(!p)throw Error('Open or create a project first');const n=node(uid(),'module',f.name,f.what,80,80,p.stage,`# ${f.name}\n\n${f.what}\n\n${f.input_output||''}`,{why:f.why,intent:f.intent,constraints:f.constraints||'',risks:f.risks||'',eval:f.eval||''});p.nodes.push(C.place(n,n.x,n.y,p.nodes));p.version++;persist(true);selectNode(n.id);const saved=window.AccountSync?await window.AccountSync.flush():!storageError;return {id:n.id,project_id:p.id,status:n.status,saved};}
function exportProject(format){const p=project();if(!p)return;const body=format==='json'?JSON.stringify({schema:2,projects:[p]},null,2):`# ${value(p.name)}\n\n${value(p.goal)}\n\n`+p.nodes.map(n=>`## ${value(n.title)}\n\n${value(n.artifact)}\n\n### ${L('证据','Evidence')}\n${value(n.evidence)}\n\n### WHY\n${value(n.why)}\n\n### INTENT\n${value(n.intent)}\n\n### EVAL\n${value(n.eval)}`).join('\n\n');const a=document.createElement('a'),url=URL.createObjectURL(new Blob([body],{type:format==='json'?'application/json;charset=utf-8':'text/markdown;charset=utf-8'}));a.href=url;a.download=value(p.name).replace(/[<>:"/\\|?*]/g,'-')+'.'+(format==='json'?'json':'md');a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.onchange=async()=>{try{const file=input.files[0];if(!file||file.size>5e6)throw Error('File must be under 5 MB');const data=JSON.parse(await file.text());if(!C.validateStore(data))throw Error('Invalid project format');for(const p of data.projects){if(!p.nodes.length||p.nodes.some(n=>!typeLabels[n.type]||!stages.some(s=>s.id===n.stage)||!statusLabels[n.status]))throw Error('Invalid artifact');if(p.edges.some(e=>!p.nodes.some(n=>n.id===e.from)||!p.nodes.some(n=>n.id===e.to)||!flowLabels[e.type]))throw Error('Invalid relationship');}data.projects.forEach(p=>{p.id=uid();p.camera=p.camera||{x:40,y:60,z:1};storeData.projects.push(p);storeData.active=p.id;});view='projects';persist(true);render();toast('项目已导入','Project imported');}catch(e){toast('导入失败：'+e.message,'Import failed: '+e.message);}};input.click();}
function drawDemo(){if(!$('#demo-board'))return;const reduced=storeData.prefs.reduce||matchMedia('(prefers-reduced-motion: reduce)').matches,index=reduced?4:demoStep;const names=[B('问题定义','Problem brief'),B('系统结构','System structure'),B('模块与决策','Modules & decisions'),B('验证证据','Verification evidence'),B('可复用知识','Reusable knowledge')];$('#demo-stages').innerHTML=names.map((n,i)=>`<div class="demo-stage ${i===index?'active':''}"><span>0${i+1}</span>${value(n)}</div>`).join('');$('#demo-board').innerHTML=names.slice(0,index+1).map((n,i)=>`<div class="demo-artifact demo-${i}"><small>${['Explore','Specify','Decide','Verify','Learn'][i]}</small><strong>${value(n)}</strong><span>${L(['明确目标与边界','职责、接口和数据流','选择与理由','预期 → 实际 → 证据','反馈进入下一次协作'][i],['Goal and boundaries','Responsibilities, interfaces, flows','Choice and rationale','Expected → actual → evidence','Feedback into the next project'][i])}</span></div>`).join('');}
function bindLocal(){const f=$('#flow-filter');if(f)f.onchange=()=>{filter=f.value;drawGraph();};const search=$('#node-search');if(search)search.oninput=()=>{query=search.value;drawGraph();};const stage=$('#project-stage');if(stage)stage.onchange=()=>{project().stage=stage.value;project().version++;persist(true);render();};$$('[data-pref]').forEach(e=>e.onchange=()=>{storeData.prefs[e.dataset.pref]=e.type==='checkbox'?e.checked:e.type==='range'?Number(e.value):e.value;persist();render();});const h=$('.resize-handle');if(h){h.onpointerdown=e=>{h.setPointerCapture(e.pointerId);h.dataset.resizing='true';};h.onpointermove=e=>{if(h.dataset.resizing!=='true')return;storeData.prefs.panelWidth=Math.min(650,Math.max(290,innerWidth-e.clientX));$('.inspector').style.setProperty('--panel-width',storeData.prefs.panelWidth+'px');};h.onpointerup=()=>{h.dataset.resizing='false';persist();};h.onkeydown=e=>{if(!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();storeData.prefs.panelWidth=Math.min(650,Math.max(290,storeData.prefs.panelWidth+(e.key==='ArrowLeft'?20:-20)));$('.inspector').style.setProperty('--panel-width',storeData.prefs.panelWidth+'px');persist();};}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const a=b.dataset.action;if(a==='select-node'&&swallowClick){swallowClick=false;return;}if(a.startsWith('view-'))return switchView(a.slice(5));switch(a){case'home':switchView('home');break;case'language':language=language==='zh'?'en':'zh';try{localStorage.setItem('adc-language',language);}catch{}render();break;case'new-project':newProjectDialog();break;case'new-at-stage':newProjectDialog(methodStage);break;case'entry':newProjectDialog(b.dataset.stage);break;case'example':openExample();break;case'open-project':storeData.active=b.dataset.id;switchView('canvas');break;case'select-node':case'open-node':selectNode(b.dataset.id);break;case'sidebar':storeData.prefs.sidebar=!storeData.prefs.sidebar;persist();render();break;case'close-detail':selected=null;full=false;render();break;case'full':full=!full;render();break;case'zoom-in':zoom(1.2);break;case'zoom-out':zoom(1/1.2);break;case'zoom-reset':zoom(1/project().camera.z);break;case'fit':fitCanvas();break;case'focus':focus=!focus;render();break;case'add-node':editNodeDialog(true);break;case'edit-node':editNodeDialog();break;case'cancel-dialog':$('#editor').close();break;case'stage':methodStage=b.dataset.stage;switchView('method');break;case'copy-stage':{const s=stages.find(v=>v.id===methodStage);try{await navigator.clipboard.writeText(`# ${stageLabel(s.id)}\n\n${s.fields.map(f=>t(f[0])+'\n'+t(f[1])).join('\n\n')}`);toast('模板已复制','Template copied');}catch{toast('无法访问剪贴板，请手动选择模板文本','Clipboard unavailable; select template text manually');}break;}case'export':showDialog(L('导出项目','Export project'),`<label class="form-field"><span>${L('格式','Format')}</span><select name="format"><option value="json">JSON · ${L('完整项目与画布','Full project and canvas')}</option><option value="md">Markdown · ${L('产物阅读','Artifact reading')}</option></select></label>`,f=>exportProject(f.format));break;case'import':importProject();break;case'demo-toggle':demoPaused=!demoPaused;render();break;case'rerun':render();toast('已重新运行：3 项断言通过','Rerun complete: 3 assertions passed');break;}});
document.addEventListener('keydown',e=>{if(e.target.matches('.graph-node')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();selectNode(e.target.dataset.id);}if(e.key==='Escape'&&!$('#editor').open&&selected){selected=null;full=false;render();}});
setInterval(()=>{if(view==='home'&&!demoPaused&&!storeData.prefs.reduce&&!matchMedia('(prefers-reduced-motion: reduce)').matches){demoStep=(demoStep+1)%5;drawDemo();}},2600);
async function registerTools(){if(!document.modelContext?.registerTool)return;const lifecycle=new AbortController();const empty={type:'object',properties:{},additionalProperties:false};const checkEmpty=v=>{if(!v||typeof v!=='object'||Object.keys(v).length)throw Error('Expected an empty object');};const tools=[{name:'read_methodology',description:'Read the nine-stage collaboration methodology or one stage. No state changes.',inputSchema:{type:'object',properties:{stage:{type:'string',enum:stages.map(s=>s.id)}},additionalProperties:false},execute:v=>{if(!v||Object.keys(v).some(k=>k!=='stage')||(v.stage&&!stages.some(s=>s.id===v.stage)))throw Error('Unknown stage');return stages.filter(s=>!v.stage||s.id===v.stage).map(s=>({id:s.id,name:stageLabel(s.id),question:t(s.question),exit:t(s.exit),...Object.fromEntries(Object.entries(stageDetails[s.id]).map(([k,v])=>[k,t(v)]))}));}},{name:'get_module_template',description:'Read the reusable module card template in the selected language.',inputSchema:empty,execute:v=>{checkEmpty(v);return {template:language==='zh'?templateZh[0]:templates[0].content};}},{name:'save_module_card',description:'Create and persist a module card in the active project, then select it visibly on the canvas. Requires an open project.',inputSchema:{type:'object',properties:Object.fromEntries(['name','what','why','intent','input_output','constraints','eval','risks'].map(k=>[k,{type:'string'}])),required:['name','what','why','intent'],additionalProperties:false},execute:saveModuleCard,write:true},{name:'read_release',description:'Read the site and methodology release metadata.',inputSchema:empty,execute:v=>{checkEmpty(v);return {site_version:'1.2',skill_version:'0.1.0',model:'GPT-5.6 Sol',timestamp:'2026-09-15T17:35:48+08:00',acceptance:'DESIGN_AI_Development_Collaboration_v1.md'};}},{name:'get_verification_plan',description:'Read the active project verification artifacts and actual fixed-fixture results when using the example.',inputSchema:empty,execute:v=>{checkEmpty(v);const p=project();if(!p)throw Error('Open a project first');return {project_id:p.id,artifacts:p.nodes.filter(n=>n.type==='verification').map(n=>({id:n.id,title:value(n.title),content:value(n.artifact),evidence:value(n.evidence),status:n.status})),fixture_results:p.example?C.evidence():null};}},{name:'read_project_state',description:'Read the active project artifacts, positions and relationships without modifying them.',inputSchema:empty,execute:v=>{checkEmpty(v);const p=project();if(!p)throw Error('Open a project first');return structuredClone(p);}}];try{for(const tool of tools){const {write,...definition}=tool;await document.modelContext.registerTool({...definition,annotations:{readOnlyHint:!write,untrustedContentHint:tool.name!=='read_release'}},{signal:lifecycle.signal});}webmcpState='ready';}catch{lifecycle.abort();webmcpState='failed';}addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
render();registerTools();
